            if (!IN6_IS_ADDR_UNSPECIFIED(&dst->sin6_addr)) {
                gateway.ipv6 = host;
            }
        }
    }

    freeifaddrs(ifap);

    return gateway;
}

} // namespace Network
} // namespace Util
```

